      part(ankle, new SphereGeometry(0.05, 8, 6), brz);
      for (const a of [-0.45, 0, 0.45]) {
        const toe = pivot(ankle, 0, 0, 0, 0, a, 0);
        part(toe, limbGeo(0.24, 0.028, 0.02, 6), drk, 0, 0, 0, -Math.PI / 2, 0, 0);
        part(toe, new ConeGeometry(0.024, 0.09, 5), brz, 0, -0.025, 0.27, Math.PI / 2 + 0.5, 0, 0);
      }
