// src/environment/Env.ts
function createEnvContext(root, quality) {
  const ctx = {
    root,
    lights: [],
    updaters: [],
    quality,
    playerOnlyLayer: 1,
    addLight(light, room, o = {}) {
      const base = light.intensity;
      const f = {
        light,
        base,
        amount: o.amount ?? 0.1,
        speed: o.speed ?? 6,
        phase: Math.random() * 100,
        room,
        gain: 1,
        far: o.far ?? true
      };
      root.add(light);
      ctx.lights.push(f);
      return f;
    }
  };
  return ctx;
}

