class OfficeRig {
  eye = new Vector3(0, 1.4, 0.5);
  doors;
  ventShutter;
  ventOpenY = 3;
  ventClosedY = 2.05;
  ventLampMat;
  glass;
  deskScreen;
  lamp;
  lampFlicker;
  fluoFlicker;
  fluoMat;
  lampBulbMat;
  clockCtx;
  clockTex;
  shards = [];
  shardTime = -1;
  fan;
  glassBroken = false;
  setClock(hoursSinceMidnight) {
    const ctx = this.clockCtx;
    const s = 256;
    ctx.fillStyle = "#d6cbb0";
    ctx.fillRect(0, 0, s, s);
    ctx.strokeStyle = "#1a1208";
    ctx.fillStyle = "#1a1208";
    ctx.lineWidth = 8;
    ctx.beginPath();
    ctx.arc(s / 2, s / 2, s / 2 - 8, 0, Math.PI * 2);
    ctx.stroke();
    for (let i = 0;i < 12; i++) {
      const a = i / 12 * Math.PI * 2;
      ctx.lineWidth = i % 3 === 0 ? 6 : 3;
      ctx.beginPath();
      ctx.moveTo(s / 2 + Math.cos(a) * 96, s / 2 + Math.sin(a) * 96);
      ctx.lineTo(s / 2 + Math.cos(a) * 112, s / 2 + Math.sin(a) * 112);
      ctx.stroke();
    }
    const h = hoursSinceMidnight % 12;
    const hourA = h / 12 * Math.PI * 2 - Math.PI / 2;
    const minA = hoursSinceMidnight % 1 * Math.PI * 2 - Math.PI / 2;
    ctx.lineCap = "round";
    ctx.lineWidth = 9;
    ctx.beginPath();
    ctx.moveTo(s / 2, s / 2);
    ctx.lineTo(s / 2 + Math.cos(hourA) * 60, s / 2 + Math.sin(hourA) * 60);
    ctx.stroke();
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(s / 2, s / 2);
    ctx.lineTo(s / 2 + Math.cos(minA) * 92, s / 2 + Math.sin(minA) * 92);
    ctx.stroke();
    this.clockTex.needsUpdate = true;
  }
  breakGlass() {
    if (this.glassBroken)
      return;
    this.glassBroken = true;
    this.glass.visible = false;
    this.shardTime = 0;
    for (const s of this.shards) {
      s.mesh.visible = true;
      s.mesh.position.set((Math.random() - 0.5) * 2.4, 1 + Math.random() * 1.2, -3.1);
      s.vel.set((Math.random() - 0.5) * 2, Math.random() * 1.5, 1.5 + Math.random() * 3.5);
      s.spin.set(Math.random() * 10, Math.random() * 10, Math.random() * 10);
    }
  }
  resetGlass() {
    this.glassBroken = false;
    this.glass.visible = true;
    this.shardTime = -1;
    for (const s of this.shards)
      s.mesh.visible = false;
  }
  update(dt) {
    this.fan.children[0].rotation.z += dt * 16;
    this.fan.rotation.y = Math.sin(performance.now() * 0.0006) * 0.6;
    if (this.shardTime >= 0) {
      this.shardTime += dt;
      for (const s of this.shards) {
        s.vel.y -= 9.8 * dt;
        s.mesh.position.addScaledVector(s.vel, dt);
        if (s.mesh.position.y < 0.02) {
          s.mesh.position.y = 0.02;
          s.vel.set(0, 0, 0);
          s.spin.set(0, 0, 0);
        }
        s.mesh.rotation.x += s.spin.x * dt;
        s.mesh.rotation.y += s.spin.y * dt;
      }
    }
  }
}
